/**
 * IDs of the top-level product categories a product belongs to (directly or via subcategories).
 */
function perfectpixel_get_product_top_categories( $product_id ) {
	$top = array();
	foreach ( wp_get_post_terms( $product_id, 'product_cat', array( 'fields' => 'ids' ) ) as $term_id ) {
		$ancestors = get_ancestors( $term_id, 'product_cat', 'taxonomy' );
		$top[]     = $ancestors ? end( $ancestors ) : $term_id;
	}
	return array_values( array_unique( array_map( 'intval', $top ) ) );
}
